itn.typescript:
// D34 · Part 1 · 한국어 역정규화(ITN) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d34_itn.ts   (글자만 주고받는 시험 · 마이크·API 키·인터넷 불필요)
//   들은 말을 시스템이 쓰는 값으로: "공일공" → 010 · "이십일" → 21 · "오후 두 시 반" → 14:30 · "다음 주 수요일" → 날짜 (오늘이 기준)
const TODAY = "2026-11-12"; // 오늘 (수업 재현을 위해 고정 · 실서비스는 new Date()) = 목요일
const WEEKDAY_KO = "월화수목금토일";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

// 날짜는 "2026-11-18" 같은 글자로 다룬다 (글자끼리 비교하면 날짜 순서와 같음)
const parseDay = (iso: string): Date => new Date(`${iso}T00:00:00Z`);
const addDays = (iso: string, k: number): string => new Date(parseDay(iso).getTime() + k * 86400000).toISOString().slice(0, 10);
const weekday = (iso: string): number => (parseDay(iso).getUTCDay() + 6) % 7; // 월 = 0 … 일 = 6
const makeDay = (y: number, m: number, d: number): string | null => {
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d ? dt.toISOString().slice(0, 10) : null; // 없는 날(2월 30일)은 null
};

// ── 1) 숫자 두 가지 읽기: 한 글자씩(공일공) · 한자어 수(이십일)
const DIG: Record<string, string> = { 공: "0", 영: "0", 빵: "0", 일: "1", 이: "2", 삼: "3", 사: "4", 오: "5", 육: "6", 륙: "6", 칠: "7", 팔: "8", 구: "9" };

function spokenDigits(s: string): string {
  // "공일공" → "010" (숫자를 한 글자씩 읽은 경우, 아라비아 숫자는 그대로)
  return [...s].filter((c) => c in DIG || /\d/.test(c)).map((c) => DIG[c] ?? c).join("");
}

const DIGIT_VAL: Record<string, number> = { 일: 1, 이: 2, 삼: 3, 사: 4, 오: 5, 육: 6, 륙: 6, 칠: 7, 팔: 8, 구: 9 };
const SMALL: Record<string, number> = { 십: 10, 백: 100, 천: 1000 };

function sinoToInt(s: string): number {
  // "이십일" → 21, "십일" → 11, "이천이십육" → 2026 ('십'처럼 앞에 숫자가 없으면 1배)
  if (/^\d+$/.test(s)) return Number(s);
  let total = 0;
  let num = 0;
  for (const ch of s) {
    if (ch in DIGIT_VAL) num = DIGIT_VAL[ch];
    else if (ch in SMALL) {
      total += (num || 1) * SMALL[ch];
      num = 0;
    }
  }
  return total + num;
}

// ── 2) 시간과 날짜: 고유어 · 한자어가 섞이고 '오늘'이 기준. 값과 함께 '확신도'도 돌려줌
const NATIVE_H: Record<string, number> = { 열두: 12, 열한: 11, 열: 10, 아홉: 9, 여덟: 8, 일곱: 7, 여섯: 6, 다섯: 5, 네: 4, 세: 3, 두: 2, 한: 1 };
const SINO_CH = "일이삼사오육칠팔구십";
const TIME_RE = new RegExp(`(오전|오후|아침|낮|저녁|밤)?\\s*(\\d{1,2}|${Object.keys(NATIVE_H).join("|")})\\s*시\\s*(반|(\\d{1,2}|[${SINO_CH}]+)\\s*분)?`);

function timeItn(text: string): [string, number] | null {
  // "오후 두 시 반" → ["14:30", 1.0]. 오전 · 오후를 안 말한 1 ~ 7시는 오후로 보되 확신을 낮춘다
  const m = TIME_RE.exec(text);
  if (!m) return null;
  const [, ampm, hS, half, mmS] = m;
  let h = /^\d+$/.test(hS) ? Number(hS) : NATIVE_H[hS];
  const mm = half === "반" ? 30 : mmS ? sinoToInt(mmS) : 0;
  let conf = 1.0;
  if (["오후", "저녁", "밤"].includes(ampm) && h < 12) h += 12; // 오후 두 시 = 14시
  else if (!ampm && h >= 1 && h <= 7) {
    h += 12;
    conf = 0.6;
  } else if (!ampm) conf = 0.8;
  return [`${String(h).padStart(2, "0")}:${String(mm).padStart(2, "0")}`, conf];
}

const REL_DAY: Record<string, number> = { 오늘: 0, 내일: 1, 모레: 2, 글피: 3 };
const WEEK_RE = /(?:(이번|다음|다다음)\s*주\s*)?([월화수목금토일])요일/;
const MD_RE = new RegExp(`(\\d{1,2}|[${SINO_CH}]+)\\s*월\\s*(\\d{1,2}|[${SINO_CH}]+)\\s*일`);

function dateItn(text: string, today: string = TODAY): [string, number] | null {
  // "다음 주 수요일" → [날짜, 확신도]. 오늘이 기준이라 같은 말도 날마다 다른 날짜가 된다
  for (const [word, k] of Object.entries(REL_DAY)) if (text.includes(word)) return [addDays(today, k), 1.0];
  let m = WEEK_RE.exec(text);
  if (m) {
    const idx = WEEKDAY_KO.indexOf(m[2]);
    const monday = addDays(today, -weekday(today));
    if (m[1]) return [addDays(monday, 7 * ({ 이번: 0, 다음: 1, 다다음: 2 } as Record<string, number>)[m[1]] + idx), 1.0];
    const d = addDays(monday, idx);
    return [d > today ? d : addDays(d, 7), 0.9]; // 말하지 않았으면 '앞으로 처음 오는' 그 요일
  }
  m = MD_RE.exec(text);
  if (m) {
    const d = makeDay(Number(today.slice(0, 4)), sinoToInt(m[1]), sinoToInt(m[2]));
    return d ? [d, 1.0] : null;
  }
  return null;
}

// ── 3) 전화번호 · 이름 · 진료: 끝까지 확인해야 하는 값
const PHONE_RE = "01[016789]-\\d{3,4}-\\d{4}";

function formatPhone(d: string): string {
  if (d.length === 11) return `${d.slice(0, 3)}-${d.slice(3, 7)}-${d.slice(7)}`;
  if (d.length === 10) return `${d.slice(0, 3)}-${d.slice(3, 6)}-${d.slice(6)}`;
  return d;
}

const phoneOk = (p: string): boolean => new RegExp(`^${PHONE_RE}$`).test(p); // 문자열 '전체'가 규칙과 맞는지

const ENDINGS = /(입니다|에요|예요|고요|구요|요)(?=\s|$|[.?!,])/g;

function phoneDigits(text: string): string {
  // 문장에서 '숫자로 읽힌 부분'만 모아 숫자열로 (한글로 읽든 아라비아 숫자로 적든 같은 값)
  const t = text.replace(ENDINGS, " ").replace("에 ", " ").replace("다시", " ");
  const chars = "0-9" + Object.keys(DIG).join("");
  const runs = t.match(new RegExp(`[${chars}][${chars}\\s\\-]*`, "g")) ?? [];
  let d = "";
  for (const r of runs) if (spokenDigits(r).length > d.length) d = spokenDigits(r); // 숫자가 가장 많이 읽힌 덩어리
  if (!phoneOk(formatPhone(d)) && d.endsWith("2") && phoneOk(formatPhone(d.slice(0, -1)))) d = d.slice(0, -1); // 끝의 '이'는 숫자 2가 아니라 조사일 수 있음
  return d;
}

const SERVICES: Record<string, string[]> = { "스케일링": ["스케일링"], "충치 치료": ["충치"], "정기 검진": ["검진"], "교정 상담": ["교정"] };

function serviceItn(text: string): [string, number] | null {
  for (const [name, keys] of Object.entries(SERVICES)) if (keys.some((k) => text.includes(k))) return [name, 1.0];
  return null;
}

const SURNAMES = new Set("김이박최정강조윤장임한오서신권황안송류전홍고문양손배백허유남심노하곽성차주우구민진나지");
const NAME_RE = /(?:이름은|성함은|저는|제 이름은)?\s*([가-힣]{2,4}?)(?:이에요|이예요|예요|입니다|이요|요|이고|라고)?\s*[.!]?$/;

function nameItn(text: string): [string, number] | null {
  // "김민준이에요" → ["김민준", 0.7]: 이름은 늘 확신을 낮게 → 꼭 확인
  const m = NAME_RE.exec(text.trim());
  return m && SURNAMES.has(m[1][0]) ? [m[1], 0.7] : null;
}

// ── 4) 말하기 좋은 값 · 확인 정책
function ro(word: string): string {
  // 조사 '(으)로': 받침이 있으면 '으로' (ㄹ 받침은 '로')
  const c = word[word.length - 1];
  if (!(c >= "가" && c <= "힣")) return word + "로";
  const jong = (c.charCodeAt(0) - 0xac00) % 28;
  return word + (jong !== 0 && jong !== 8 ? "으로" : "로");
}

const sinoDigits = (g: string): string => [...g].map((c) => "공일이삼사오육칠팔구"[Number(c)]).join("");

function sayValue(slot: string, v: string): string {
  // 확인 문장에 넣을 '말하기 좋은' 값 (화면용 14:00 · 010-1234-5678을 그대로 읽지 않는다)
  if (slot === "date") return `${Number(v.slice(5, 7))}월 ${Number(v.slice(8, 10))}일 ${WEEKDAY_KO[weekday(v)]}요일`;
  if (slot === "time") {
    const [h, m] = v.split(":").map(Number);
    const h12 = h <= 12 ? h : h - 12;
    return `${h < 12 ? "오전" : "오후"} ${h12}시` + (m === 30 ? " 반" : m ? ` ${m}분` : "");
  }
  if (slot === "phone") return v.split("-").map(sinoDigits).join(", "); // 공일공, 일이삼사, 오육칠팔 (묶음마다 쉼)
  if (slot === "name") return `${v} 님`;
  return v;
}

const CRITICAL = new Set(["name", "phone"]); // 틀리면 예약 자체가 쓸모없어지는 값 → 늘 명시적 확인
const CONF_TH = 0.8; // 이보다 확신이 낮으면 명시적 확인

const confirmStyle = (slot: string, conf: number): string => (CRITICAL.has(slot) || conf < CONF_TH ? "explicit" : "implicit");

// ── 5) 대화 상태 머신
const SLOTS = ["service", "date", "time", "name", "phone"]; // 묻는 순서
const SAY_ORDER = ["date", "time", "service", "name", "phone"]; // 되말할 때의 순서 (자연스러운 말 순서)
const ASK: Record<string, string> = {
  service: "어떤 진료로 예약해 드릴까요? 스케일링, 충치 치료, 정기 검진처럼 말씀해 주세요.",
  date: "며칠에 오시겠어요?",
  time: "몇 시가 편하세요?",
  name: "예약하시는 분 성함을 말씀해 주세요.",
  phone: "연락받으실 휴대폰 번호를 말씀해 주세요.",
};
const HINT: Record<string, string> = {
  service: "예를 들어 '스케일링'이나 '충치 치료'처럼요.",
  date: "'다음 주 수요일'이나 '11월 20일'처럼 말씀해 주세요.",
  time: "'오후 두 시'처럼 말씀해 주세요.",
  name: "성함만 천천히 한 번 더 말씀해 주세요.",
  phone: "공일공부터 숫자만 천천히 말씀해 주세요.",
};
const MAX_MISS = 3; // 못 알아들음 3번 → 상담원
const MAX_SILENCE = 2; // 침묵 2번 → 종료 안내
const SILENCE = "(침묵)";
const YES_RE = /^(네|예|맞아요|맞습니다|맞아|응|그래요|좋아요|그렇습니다)/;
const NO_RE = /^(아니|아뇨|틀렸|틀려요)/;
const HANDOFF_RE = /상담원|사람이랑|사람하고|직원/;
const RESTART_RE = /처음부터/;
const BOOK_RE = /예약/;
const FAQ_RE = /주차|몇 시까지|진료 시간|영업|위치|어디|오시는 길|얼마|비용|가격/;
const FAQ_ANSWERS: [string, string][] = [
  ["주차", "건물 지하 주차장을 이용하시면 진료 당일 두 시간 무료입니다."],
  ["비용", "스케일링은 보험 적용 시 약 1만 5천 원입니다."],
  ["얼마", "스케일링은 보험 적용 시 약 1만 5천 원입니다."],
  ["진료 시간", "평일은 오전 아홉 시 반부터 오후 여섯 시 반까지 진료합니다."],
];

let mockLlm = (question: string): string => {
  // LLM 대신(대체 경로: API 키 · 인터넷 없이) 키워드로 FAQ 답을 고르는 흉내
  return FAQ_ANSWERS.find(([k]) => question.includes(k))?.[1] ?? "죄송해요, 그 부분은 정확히 안내해 드리기 어려워요.";
};

type Reply = { kind: string; text: string };
type Found = Record<string, [string, number]>;
type Slots = Record<string, string>;

function checkRules(slots: Slots, today: string = TODAY): [string, string] | null {
  // 진료 규칙: 지난 날 · 일요일 · 진료 시간 밖 (평일 9:30 ~ 18:30, 토요일 ~ 13:00, 마지막 접수는 마감 30분 전)
  const d = slots.date;
  const t = slots.time;
  if (d !== undefined && d < today) return ["date", "지난 날짜예요."];
  if (d !== undefined && weekday(d) === 6) return ["date", "일요일은 쉬어요."];
  if (t !== undefined) {
    const [h, m] = t.split(":").map(Number);
    const last = d !== undefined && weekday(d) === 5 ? 12 * 60 + 30 : 18 * 60;
    if (!(9 * 60 + 30 <= h * 60 + m && h * 60 + m <= last)) return ["time", "진료 시간은 평일 9시 반부터 6시 반, 토요일은 1시까지예요."];
  }
  return null;
}

class DialogManager {
  // 슬롯 채우기 · 확인 · 복구 · 침묵 · 맞장구를 한 곳에서 정하는 상태 머신. state: collect → confirm_slot → … → confirm_final → done (end · handoff도)
  today: string;
  slots: Slots = {};
  state: string = "collect";
  pending: [string, string] | null = null;
  miss: number = 0;
  silence: number = 0;
  phoneBuf: string = "";
  question: string = ASK.service;
  constructor(today: string = TODAY) {
    this.today = today;
  }

  need(): string | undefined {
    return SLOTS.find((s) => !(s in this.slots));
  }

  ask(prefix: string = ""): string {
    this.question = ASK[this.need() as string];
    return prefix + this.question;
  }

  finish(state: string, text: string): Reply {
    this.state = state;
    return { kind: state, text };
  }

  heard(text: string): Found {
    const out: Found = {};
    const fns: [string, (t: string) => [string, number] | null][] = [["service", serviceItn], ["date", (t) => dateItn(t, this.today)], ["time", timeItn]];
    for (const [slot, fn] of fns) {
      const r = fn(text);
      if (r) out[slot] = r;
    }
    return out;
  }

  summary(): string {
    const s = this.slots;
    return `${sayValue("date", s.date)} ${sayValue("time", s.time)}, ${s.service}, ${sayValue("name", s.name)}, 번호 ${sayValue("phone", s.phone)}`;
  }

  step(user: string): Reply {
    const t = user.trim();
    if (["done", "end", "handoff"].includes(this.state)) return { kind: this.state, text: "이미 마쳤어요." };
    if (t === SILENCE) return this.onSilence();
    this.silence = 0;
    if (HANDOFF_RE.test(t)) return this.finish("handoff", "상담원에게 연결해 드릴게요. 잠시만 기다려 주세요.");
    if (RESTART_RE.test(t)) {
      this.slots = {};
      this.pending = null;
      this.phoneBuf = "";
      this.state = "collect";
      return { kind: "restart", text: this.ask("처음부터 다시 할게요. ") };
    }
    if (this.state === "confirm_slot") return this.onConfirmSlot(t);
    if (this.state === "confirm_final") return this.onConfirmFinal(t);
    return this.collect(t);
  }

  onSilence(): Reply {
    this.silence++;
    if (this.silence >= MAX_SILENCE) return this.finish("end", "말씀이 없으셔서 통화를 마칠게요. 필요하시면 다시 전화 주세요.");
    return { kind: "silence", text: "여보세요, 듣고 계신가요? " + this.question };
  }

  explicit(slot: string, value: string, prefix: string = ""): Reply {
    this.pending = [slot, value];
    this.state = "confirm_slot";
    this.question = `${sayValue(slot, value)} 맞으세요?`;
    return { kind: "confirm", text: prefix + this.question };
  }

  nextOrFinal(prefix: string): Reply {
    if (this.need()) {
      this.state = "collect";
      return { kind: "ask", text: this.ask(prefix) };
    }
    const bad = checkRules(this.slots, this.today);
    if (bad) {
      delete this.slots[bad[0]]; // 규칙에 걸린 값만 비우고 그 슬롯부터 다시 묻는다
      this.state = "collect";
      return { kind: "rule", text: this.ask(bad[1] + " ") };
    }
    this.state = "confirm_final";
    this.question = this.summary() + " 맞으세요?";
    return { kind: "confirm", text: prefix + this.question };
  }

  onConfirmSlot(t: string): Reply {
    const [slot, value] = this.pending as [string, string];
    if (YES_RE.test(t)) {
      this.slots[slot] = value;
      this.pending = null;
      this.state = "collect";
      return this.nextOrFinal("");
    }
    this.pending = null;
    this.state = "collect";
    if (NO_RE.test(t)) return { kind: "repair", text: this.ask("다시 말씀해 주세요. " + HINT[slot] + " ") };
    return this.collect(t); // '네/아니요' 없이 새 값을 말한 경우
  }

  onConfirmFinal(t: string): Reply {
    if (YES_RE.test(t)) return this.finish("done", `예약이 완료됐어요. ${this.summary()}. 문자로 안내해 드릴게요.`);
    const found = this.heard(t);
    if (Object.keys(found).length === 0) {
      this.state = "collect";
      return { kind: "repair", text: "어떤 걸 바꿀까요? 날짜나 시간처럼 말씀해 주세요." };
    }
    for (const [slot, [v]] of Object.entries(found)) this.slots[slot] = v;
    return this.nextOrFinal("네, 바꿨어요. ");
  }

  collect(t: string): Reply {
    const need = this.need() as string;
    if (need === "phone") {
      const d = phoneDigits(t);
      if (d.length >= 3) {
        this.phoneBuf += d;
        const n = this.phoneBuf.length;
        if (n < 9) return { kind: "backchannel", text: "네, 이어서 말씀해 주세요." }; // 맞장구: 번호를 끊어 말하는 중
        const p = formatPhone(this.phoneBuf);
        this.phoneBuf = "";
        if ((n === 10 || n === 11) && phoneOk(p)) return this.explicit("phone", p);
        return this.missReply("번호 자릿수가 맞지 않아요. ", "phone");
      }
    }
    const found = this.heard(t);
    if (need === "name" && Object.keys(found).length === 0) {
      const n = nameItn(t);
      if (n) return this.explicit("name", n[0]);
    }
    if (Object.keys(found).length === 0) {
      if (FAQ_RE.test(t)) return { kind: "free", text: mockLlm(t) + " " + this.ask("그럼 하던 예약으로 돌아갈게요. ") }; // 예약 밖 질문 → 하이브리드
      if (BOOK_RE.test(t)) return { kind: "ask", text: this.ask("예약 도와드릴게요. ") };
      return this.missReply("", need);
    }
    this.miss = 0;
    const said: [string, string, boolean][] = [];
    let low: [string, string] | null = null;
    for (const slot of ["service", "date", "time"]) {
      if (!(slot in found)) continue;
      const [v, c] = found[slot];
      if (confirmStyle(slot, c) === "explicit") {
        low = low ?? [slot, v];
        continue;
      }
      const changed = slot in this.slots && this.slots[slot] !== v;
      this.slots[slot] = v;
      said.push([slot, v, changed]);
    }
    let head = "";
    if (said.length) {
      said.sort((a, b) => SAY_ORDER.indexOf(a[0]) - SAY_ORDER.indexOf(b[0]));
      head = "네, " + said.map(([s, v]) => sayValue(s, v)).join(" ") + (said.some((x) => x[2]) ? " 바꿀게요. " : " 확인했어요. ");
    }
    return low ? this.explicit(low[0], low[1], head) : this.nextOrFinal(head);
  }

  missReply(prefix: string, slot: string): Reply {
    this.miss++;
    if (this.miss >= MAX_MISS) return this.finish("handoff", "잘 알아듣지 못해 죄송해요. 상담원에게 연결해 드릴게요.");
    return { kind: "repair", text: prefix + HINT[slot] + " " + this.ask() };
  }
}

function run(turns: string[], today: string = TODAY): [DialogManager, [string, string, string, string][]] {
  // 손님 말 목록을 차례로 넣어 [대화 관리자, [손님 말, 비서 답, 답 종류, 그때 상태]] 를 돌려준다
  const dm = new DialogManager(today);
  const log: [string, string, string, string][] = [];
  for (const u of turns) {
    const r = dm.step(u);
    log.push([u, r.text, r.kind, dm.state]);
  }
  return [dm, log];
}

const SCENARIOS: [string, string[], Record<string, string>][] = [
  ["① 한 번에 다 말함", ["다음 주 수요일 오후 두 시에 스케일링 예약하고 싶어요", "김민준이요", "네", "공일공 일이삼사 오육칠팔", "네", "네"], { state: "done", date: "2026-11-18", time: "14:00", service: "스케일링", phone: "010-1234-5678" }],
