def verdict(dm: DialogManager, want: dict) -> bool:
    got = {"state": dm.state, **dm.slots}
    return all(got.get(k) == v for k, v in want.items())


# 1) 한 마디에서 몇 가지가 잡히나 (heard = 진료 · 날짜 · 시간을 한 번에)
dm = DialogManager()
cases = {"다음 주 수요일 오후 두 시에 스케일링이요": {"service", "date", "time"}, "세 시요": {"time"}, "수요일이요": {"date"},
         "충치 치료 받고 싶어요": {"service"}, "안녕하세요": set()}
for u, want in cases.items():
    got = set(dm.heard(u))
    print(f"{u:<32} → {sorted(got)}")
check(all(set(dm.heard(u)) == w for u, w in cases.items()), "한 마디에 말한 값은 모두 잡아야 해요.")

# 2) 슬롯을 채우면 '다음에 물을 것'이 앞으로 간다
dm = DialogManager()
steps = []
for u in ["다음 주 수요일 오후 두 시에 스케일링이요", "김민준이요", "네"]:
    r = dm.step(u)
    steps.append(dm.need())
    print(f"손님: {u}\n  비서({r.kind}): {r.text}\n  남은 질문 → {dm.need()}")
check(steps == ["name", "name", "phone"], "진료 · 날짜 · 시간이 한 번에 채워지면 바로 이름을 묻고, 이름 확인 뒤 번호를 물어요.")
check(dm.slots["service"] == "스케일링" and dm.slots["date"] == date(2026, 11, 18) and dm.slots["time"] == "14:00" and dm.slots["name"] == "김민준", "채워진 값이 맞아야 해요.")

# 3) 이미 채운 슬롯을 다시 말하면 '바꾸기'
r = dm.step("아 잠깐만요, 목요일로 할게요")
print(f"말 바꾸기: {r.text}")
check(dm.slots["date"] == date(2026, 11, 19) and "바꿀게요" in r.text, "새로 말한 값이 이전 값을 덮어쓰고 비서가 알려 줘야 해요.")

# 4) 예약 규칙 검사: 지난 날 · 일요일 · 진료 시간 밖은 슬롯을 비우고 다시 묻는다
for slots, want in [({"date": date(2026, 11, 8), "time": "14:00"}, "date"), ({"date": date(2026, 11, 15), "time": "14:00"}, "date"),
                    ({"date": date(2026, 11, 18), "time": "20:00"}, "time"), ({"date": date(2026, 11, 14), "time": "15:00"}, "time"),
                    ({"date": date(2026, 11, 18), "time": "14:00"}, None)]:
    bad = check_rules(slots)
    print(f"{slots['date']} {slots['time']} → {bad}")
