     {"state": "done", "service": "교정 상담"}),
    ("⑨ 마지막 확인에서 '아니요'", ["다음 주 월요일 오전 열한 시 충치 치료", "강도윤입니다", "네", "공일공 일일일일 이이이이", "네", "아니요 오후 세 시로 해 주세요", "네"],
     {"state": "done", "time": "15:00"}),
]


def verdict(dm: DialogManager, want: dict) -> bool:
    got = {"state": dm.state, **dm.slots}
    return all(got.get(k) == v for k, v in want.items())


def show(log):
    for u, a, kind, state in log:
        print(f"  손님: {u}\n  비서({kind}/{state}): {a}")


# 1) 번호 자릿수가 틀리면: 9자리만 들었으니 처음부터 다시 (맞장구 없이 '자릿수가 맞지 않아요')
dm, log = run(["다음 주 금요일 오전 열 시 정기 검진", "최유나요", "네", "공일공 일이삼 사오육", "공일공 일이삼사 오육칠팔", "네", "네"])
