function verdict(dm: DialogManager, want: Record<string, string>): boolean {
  const got: Record<string, string> = { state: dm.state, ...dm.slots };
  return Object.entries(want).every(([k, v]) => got[k] === v);
}

const show = (log: [string, string, string, string][]): void => log.forEach(([u, a, kind, state]) => console.log(`  손님: ${u}\n  비서(${kind}/${state}): ${a}`));

// 1) 번호 자릿수가 틀리면: 9자리만 들었으니 처음부터 다시 (맞장구 없이 '자릿수가 맞지 않아요')
let [dm, log] = run(["다음 주 금요일 오전 열 시 정기 검진", "최유나요", "네", "공일공 일이삼 사오육", "공일공 일이삼사 오육칠팔", "네", "네"]);
