class FakeSession:
    def __init__(self):
        self.said, self.closed, self.handlers = [], False, {}

    def on(self, event):
        return lambda fn: self.handlers.setdefault(event, fn)


def wire_silence(session: FakeSession, dm: DialogManager):
    @session.on("user_state_changed")
    def _on_user_state(new_state):
        if new_state == "away":                  # 손님이 AWAY_SEC초 동안 조용함
            r = dm.on_silence()
            session.said.append(r.text)
            if r.kind == "end":
                session.closed = True


