# D34 · Part 3 · 대화 상태 머신 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치할 것 없음 · Python 표준 라이브러리만)
# 실행: python d34_states.py   (글자만 주고받는 시험 · 마이크·API 키·인터넷 불필요)
#   대화 상태 머신: collect → confirm_slot → … → confirm_final → done (그리고 end · handoff). 시나리오를 돌리며 상태 이동을 표로 확인
import re
from datetime import date, timedelta

TODAY = date(2026, 11, 12)                       # 오늘 (수업 재현을 위해 고정 · 실서비스는 date.today()) = 목요일
WEEKDAY_KO = "월화수목금토일"


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


# ── 1) 숫자 두 가지 읽기: 한 글자씩(공일공) · 한자어 수(이십일)
DIG = {"공": "0", "영": "0", "빵": "0", "일": "1", "이": "2", "삼": "3", "사": "4", "오": "5",
       "육": "6", "륙": "6", "칠": "7", "팔": "8", "구": "9"}


def spoken_digits(s: str) -> str:
    """"공일공" → "010" (숫자를 한 글자씩 읽은 경우, 아라비아 숫자는 그대로)"""
    return "".join(DIG.get(c, c) for c in s if c in DIG or c.isdigit())


DIGIT_VAL = {"일": 1, "이": 2, "삼": 3, "사": 4, "오": 5, "육": 6, "륙": 6, "칠": 7, "팔": 8, "구": 9}
SMALL = {"십": 10, "백": 100, "천": 1000}


def sino_to_int(s: str) -> int:
    """"이십일" → 21, "십일" → 11, "이천이십육" → 2026 ('십'처럼 앞에 숫자가 없으면 1배)"""
    if s.isdigit():
        return int(s)
    total, num = 0, 0
    for ch in s:
        if ch in DIGIT_VAL:
            num = DIGIT_VAL[ch]
        elif ch in SMALL:
            total += (num or 1) * SMALL[ch]
            num = 0
    return total + num


# ── 2) 시간과 날짜: 고유어 · 한자어가 섞이고 '오늘'이 기준. 값과 함께 '확신도'도 돌려줌
NATIVE_H = {"열두": 12, "열한": 11, "열": 10, "아홉": 9, "여덟": 8, "일곱": 7, "여섯": 6, "다섯": 5, "네": 4, "세": 3, "두": 2, "한": 1}
SINO_CH = "일이삼사오육칠팔구십"
TIME_RE = re.compile(r"(오전|오후|아침|낮|저녁|밤)?\s*(\d{1,2}|" + "|".join(NATIVE_H) + r")\s*시\s*(반|(\d{1,2}|[" + SINO_CH + r"]+)\s*분)?")


def time_itn(text: str):
    """"오후 두 시 반" → ("14:30", 1.0). 오전 · 오후를 안 말한 1 ~ 7시는 오후로 보되 확신을 낮춘다"""
    m = TIME_RE.search(text)
    if not m:
        return None
    ampm, h_s, half, mm_s = m.group(1), m.group(2), m.group(3), m.group(4)
    h = int(h_s) if h_s.isdigit() else NATIVE_H[h_s]
    mm = 30 if half == "반" else (sino_to_int(mm_s) if mm_s else 0)
    conf = 1.0
    if ampm in ("오후", "저녁", "밤") and h < 12:
        h += 12                                  # 오후 두 시 = 14시
    elif ampm is None and 1 <= h <= 7:
        h += 12
        conf = 0.6
    elif ampm is None:
        conf = 0.8
    return f"{h:02d}:{mm:02d}", conf


REL_DAY = {"오늘": 0, "내일": 1, "모레": 2, "글피": 3}
WEEK_RE = re.compile(r"(?:(이번|다음|다다음)\s*주\s*)?([월화수목금토일])요일")
MD_RE = re.compile(r"(\d{1,2}|[" + SINO_CH + r"]+)\s*월\s*(\d{1,2}|[" + SINO_CH + r"]+)\s*일")


def date_itn(text: str, today: date = TODAY):
    """"다음 주 수요일" → (date, 확신도). 오늘이 기준이라 같은 말도 날마다 다른 날짜가 된다"""
    for word, k in REL_DAY.items():
        if word in text:
            return today + timedelta(days=k), 1.0
    m = WEEK_RE.search(text)
    if m:
        prefix, idx = m.group(1), WEEKDAY_KO.index(m.group(2))
        monday = today - timedelta(days=today.weekday())
        if prefix:
            return monday + timedelta(days=7 * {"이번": 0, "다음": 1, "다다음": 2}[prefix] + idx), 1.0
        d = monday + timedelta(days=idx)
        return (d if d > today else d + timedelta(days=7)), 0.9      # 말하지 않았으면 '앞으로 처음 오는' 그 요일
    m = MD_RE.search(text)
    if m:
        try:
            return date(today.year, sino_to_int(m.group(1)), sino_to_int(m.group(2))), 1.0
        except ValueError:
            return None
    return None


# ── 3) 전화번호 · 이름 · 진료: 끝까지 확인해야 하는 값
PHONE_RE = r"01[016789]-\d{3,4}-\d{4}"


def format_phone(d: str) -> str:
    if len(d) == 11:
        return f"{d[:3]}-{d[3:7]}-{d[7:]}"
    if len(d) == 10:
        return f"{d[:3]}-{d[3:6]}-{d[6:]}"
    return d


def phone_ok(p: str) -> bool:
    return re.fullmatch(PHONE_RE, p) is not None            # 문자열 '전체'가 규칙과 맞는지


ENDINGS = re.compile(r"(입니다|에요|예요|고요|구요|요)(?=\s|$|[.?!,])")


def phone_digits(text: str) -> str:
    """문장에서 '숫자로 읽힌 부분'만 모아 숫자열로 (한글로 읽든 아라비아 숫자로 적든 같은 값)"""
    t = ENDINGS.sub(" ", text).replace("에 ", " ").replace("다시", " ")
    chars = "0-9" + "".join(DIG)
    runs = re.findall(f"[{chars}][{chars}\\s\\-]*", t)
    d = spoken_digits(max(runs, key=lambda r: len(spoken_digits(r)), default=""))
    if not phone_ok(format_phone(d)) and d.endswith("2") and phone_ok(format_phone(d[:-1])):
        d = d[:-1]                               # 끝의 '이'는 숫자 2가 아니라 '…팔이에요'의 조사일 수 있음
    return d


SERVICES = {"스케일링": ["스케일링"], "충치 치료": ["충치"], "정기 검진": ["검진"], "교정 상담": ["교정"]}


def service_itn(text: str):
    for name, keys in SERVICES.items():
        if any(k in text for k in keys):
            return name, 1.0
    return None


SURNAMES = set("김이박최정강조윤장임한오서신권황안송류전홍고문양손배백허유남심노하곽성차주우구민진나지")
NAME_RE = re.compile(r"(?:이름은|성함은|저는|제 이름은)?\s*([가-힣]{2,4}?)(?:이에요|이예요|예요|입니다|이요|요|이고|라고)?\s*[.!]?$")


def name_itn(text: str):
    """"김민준이에요" → ("김민준", 0.7): 이름은 늘 확신을 낮게 → 꼭 확인"""
    m = NAME_RE.search(text.strip())
    if not m or m.group(1)[0] not in SURNAMES:
        return None
    return m.group(1), 0.7

# ── 4) 말하기 좋은 값 · 확인 정책
def ro(word: str) -> str:
    """조사 '(으)로': 받침이 있으면 '으로' (ㄹ 받침은 '로')"""
    c = word[-1]
    if not ("가" <= c <= "힣"):
        return word + "로"
    jong = (ord(c) - 0xAC00) % 28
    return word + ("으로" if jong not in (0, 8) else "로")


def sino_digits(g: str) -> str:
    return "".join("공일이삼사오육칠팔구"[int(c)] for c in g)


def say_value(slot: str, v) -> str:
    """확인 문장에 넣을 '말하기 좋은' 값 (화면용 14:00 · 010-1234-5678을 그대로 읽지 않는다)"""
    if slot == "date":
        return f"{v.month}월 {v.day}일 {WEEKDAY_KO[v.weekday()]}요일"
    if slot == "time":
        h, m = map(int, v.split(":"))
        h12 = h if h <= 12 else h - 12
        return f"{'오전' if h < 12 else '오후'} {h12}시" + (" 반" if m == 30 else (f" {m}분" if m else ""))
    if slot == "phone":
        return ", ".join(sino_digits(g) for g in v.split("-"))      # 공일공, 일이삼사, 오육칠팔 (묶음마다 쉼)
    if slot == "name":
        return f"{v} 님"
    return v


CRITICAL = {"name", "phone"}                     # 틀리면 예약 자체가 쓸모없어지는 값 → 늘 명시적 확인
CONF_TH = 0.8                                    # 이보다 확신이 낮으면 명시적 확인


def confirm_style(slot: str, conf: float) -> str:
    return "explicit" if slot in CRITICAL or conf < CONF_TH else "implicit"


# ── 5) 대화 상태 머신
SLOTS = ["service", "date", "time", "name", "phone"]          # 묻는 순서
SAY_ORDER = ["date", "time", "service", "name", "phone"]       # 되말할 때의 순서 (자연스러운 말 순서)
ASK = {"service": "어떤 진료로 예약해 드릴까요? 스케일링, 충치 치료, 정기 검진처럼 말씀해 주세요.",
       "date": "며칠에 오시겠어요?", "time": "몇 시가 편하세요?",
       "name": "예약하시는 분 성함을 말씀해 주세요.", "phone": "연락받으실 휴대폰 번호를 말씀해 주세요."}
HINT = {"service": "예를 들어 '스케일링'이나 '충치 치료'처럼요.", "date": "'다음 주 수요일'이나 '11월 20일'처럼 말씀해 주세요.",
        "time": "'오후 두 시'처럼 말씀해 주세요.", "name": "성함만 천천히 한 번 더 말씀해 주세요.", "phone": "공일공부터 숫자만 천천히 말씀해 주세요."}
MAX_MISS, MAX_SILENCE = 3, 2                     # 못 알아들음 3번 → 상담원 · 침묵 2번 → 종료 안내
SILENCE = "(침묵)"
YES_RE = re.compile(r"^(네|예|맞아요|맞습니다|맞아|응|그래요|좋아요|그렇습니다)")
NO_RE = re.compile(r"^(아니|아뇨|틀렸|틀려요)")
HANDOFF_RE = re.compile(r"상담원|사람이랑|사람하고|직원")
RESTART_RE = re.compile(r"처음부터")
BOOK_RE = re.compile(r"예약")
FAQ_RE = re.compile(r"주차|몇 시까지|진료 시간|영업|위치|어디|오시는 길|얼마|비용|가격")
FAQ_ANSWERS = [("주차", "건물 지하 주차장을 이용하시면 진료 당일 두 시간 무료입니다."),
               ("비용", "스케일링은 보험 적용 시 약 1만 5천 원입니다."), ("얼마", "스케일링은 보험 적용 시 약 1만 5천 원입니다."),
               ("진료 시간", "평일은 오전 아홉 시 반부터 오후 여섯 시 반까지 진료합니다.")]


def mock_llm(question: str) -> str:
    """LLM 대신(대체 경로: API 키 · 인터넷 없이) 키워드로 FAQ 답을 고르는 흉내"""
    return next((a for k, a in FAQ_ANSWERS if k in question), "죄송해요, 그 부분은 정확히 안내해 드리기 어려워요.")


class Reply:
    def __init__(self, kind: str, text: str):
        self.kind, self.text = kind, text


def check_rules(slots: dict, today: date = TODAY):
    """진료 규칙: 지난 날 · 일요일 · 진료 시간 밖 (평일 9:30 ~ 18:30, 토요일 ~ 13:00, 마지막 접수는 마감 30분 전)"""
    d, t = slots.get("date"), slots.get("time")
    if d is not None and d < today:
        return "date", "지난 날짜예요."
    if d is not None and d.weekday() == 6:
        return "date", "일요일은 쉬어요."
    if t is not None:
        h, m = map(int, t.split(":"))
        last = 12 * 60 + 30 if d is not None and d.weekday() == 5 else 18 * 60
        if not (9 * 60 + 30 <= h * 60 + m <= last):
            return "time", "진료 시간은 평일 9시 반부터 6시 반, 토요일은 1시까지예요."
    return None


class DialogManager:
    """슬롯 채우기 · 확인 · 복구 · 침묵 · 맞장구를 한 곳에서 정하는 상태 머신. state: collect → confirm_slot → … → confirm_final → done (end · handoff도)"""

    def __init__(self, today: date = TODAY):
        self.today, self.slots, self.state = today, {}, "collect"
        self.pending, self.miss, self.silence, self.phone_buf, self.question = None, 0, 0, "", ASK["service"]

    def need(self):
        return next((s for s in SLOTS if s not in self.slots), None)

    def ask(self, prefix: str = "") -> str:
        s = self.need()
        self.question = ASK[s]
        return prefix + self.question

    def finish(self, state: str, text: str) -> Reply:
        self.state = state
        return Reply(state, text)

    def heard(self, text: str) -> dict:
        out = {}
        for slot, fn in [("service", service_itn), ("date", lambda t: date_itn(t, self.today)), ("time", time_itn)]:
            r = fn(text)
            if r:
                out[slot] = r
        return out

    def summary(self) -> str:
        s = self.slots
        return f"{say_value('date', s['date'])} {say_value('time', s['time'])}, {s['service']}, {say_value('name', s['name'])}, 번호 {say_value('phone', s['phone'])}"

    def step(self, user: str) -> Reply:
        t = user.strip()
        if self.state in ("done", "end", "handoff"):
            return Reply(self.state, "이미 마쳤어요.")
        if t == SILENCE:
            return self.on_silence()
        self.silence = 0
        if HANDOFF_RE.search(t):
            return self.finish("handoff", "상담원에게 연결해 드릴게요. 잠시만 기다려 주세요.")
        if RESTART_RE.search(t):
            self.slots, self.pending, self.phone_buf, self.state = {}, None, "", "collect"
            return Reply("restart", self.ask("처음부터 다시 할게요. "))
        if self.state == "confirm_slot":
            return self.on_confirm_slot(t)
        if self.state == "confirm_final":
            return self.on_confirm_final(t)
        return self.collect(t)

    def on_silence(self) -> Reply:
        self.silence += 1
        if self.silence >= MAX_SILENCE:
            return self.finish("end", "말씀이 없으셔서 통화를 마칠게요. 필요하시면 다시 전화 주세요.")
        return Reply("silence", "여보세요, 듣고 계신가요? " + self.question)

    def explicit(self, slot: str, value, prefix: str = "") -> Reply:
        self.pending, self.state = (slot, value), "confirm_slot"
        self.question = f"{say_value(slot, value)} 맞으세요?"
        return Reply("confirm", prefix + self.question)

    def next_or_final(self, prefix: str) -> Reply:
        if self.need():
            self.state = "collect"
            return Reply("ask", self.ask(prefix))
        bad = check_rules(self.slots, self.today)
        if bad:
            del self.slots[bad[0]]                # 규칙에 걸린 값만 비우고 그 슬롯부터 다시 묻는다
            self.state = "collect"
            return Reply("rule", self.ask(bad[1] + " "))
        self.state = "confirm_final"
        self.question = self.summary() + " 맞으세요?"
        return Reply("confirm", prefix + self.question)

    def on_confirm_slot(self, t: str) -> Reply:
        slot, value = self.pending
        if YES_RE.search(t):
            self.slots[slot], self.pending, self.state = value, None, "collect"
            return self.next_or_final("")
        self.pending, self.state = None, "collect"
        if NO_RE.search(t):
            return Reply("repair", self.ask("다시 말씀해 주세요. " + HINT[slot] + " "))
        return self.collect(t)                   # '네/아니요' 없이 새 값을 말한 경우

    def on_confirm_final(self, t: str) -> Reply:
        if YES_RE.search(t):
            return self.finish("done", f"예약이 완료됐어요. {self.summary()}. 문자로 안내해 드릴게요.")
        found = self.heard(t)
        if not found:
            self.state = "collect"
            return Reply("repair", "어떤 걸 바꿀까요? 날짜나 시간처럼 말씀해 주세요.")
        for slot, (v, _) in found.items():
            self.slots[slot] = v
        return self.next_or_final("네, 바꿨어요. ")

    def collect(self, t: str) -> Reply:
        need = self.need()
        if need == "phone":
            d = phone_digits(t)
            if len(d) >= 3:
                self.phone_buf += d
                n = len(self.phone_buf)
                if n < 9:
                    return Reply("backchannel", "네, 이어서 말씀해 주세요.")           # 맞장구: 번호를 끊어 말하는 중
                p = format_phone(self.phone_buf)
                if n in (10, 11) and phone_ok(p):
                    self.phone_buf = ""
                    return self.explicit("phone", p)
                self.phone_buf = ""
                return self.miss_reply("번호 자릿수가 맞지 않아요. ", "phone")
        found = self.heard(t)
        if need == "name" and not found:
            n = name_itn(t)
            if n:
                return self.explicit("name", n[0])
        if not found:
            if FAQ_RE.search(t):                 # 예약 밖 질문 → 하이브리드: LLM이 답하고 하던 질문으로 돌아옴
                return Reply("free", mock_llm(t) + " " + self.ask("그럼 하던 예약으로 돌아갈게요. "))
            if BOOK_RE.search(t):
                return Reply("ask", self.ask("예약 도와드릴게요. "))
            return self.miss_reply("", need)
        self.miss = 0
        said, low = [], None
        for slot in ("service", "date", "time"):
            if slot not in found:
                continue
            v, c = found[slot]
            if confirm_style(slot, c) == "explicit":
                low = low or (slot, v)
                continue
            word = "바꿀게요" if slot in self.slots and self.slots[slot] != v else "확인했어요"
            self.slots[slot] = v
            said.append((slot, v, word))
        head = ""
        if said:
            head = "네, " + " ".join(say_value(s, v) for s, v, _ in sorted(said, key=lambda x: SAY_ORDER.index(x[0]))) + (" 바꿀게요. " if any(w == "바꿀게요" for _, _, w in said) else " 확인했어요. ")
        if low:
            return self.explicit(low[0], low[1], head)
        return self.next_or_final(head)

    def miss_reply(self, prefix: str, slot) -> Reply:
        self.miss += 1
        if self.miss >= MAX_MISS:
            return self.finish("handoff", "잘 알아듣지 못해 죄송해요. 상담원에게 연결해 드릴게요.")
        return Reply("repair", prefix + (HINT[slot] if slot else "") + " " + (self.ask() if slot else ""))


def run(turns, today: date = TODAY):
    """손님 말 목록을 차례로 넣어 (대화 관리자, [(손님 말, 비서 답, 답 종류, 그때 상태)]) 를 돌려준다"""
    dm, log = DialogManager(today), []
    for u in turns:
        r = dm.step(u)
        log.append((u, r.text, r.kind, dm.state))
    return dm, log


D = lambda m, d: date(2026, m, d)
