     {"state": "done", "time": "15:00"}),
]


def verdict(dm: DialogManager, want: dict) -> bool:
    got = {"state": dm.state, **dm.slots}
    return all(got.get(k) == v for k, v in want.items())


# 1) ITN: 말한 그대로가 아니라 시스템이 쓰는 값으로
check(spoken_digits("공일공") == "010" and sino_to_int("이십일") == 21 and time_itn("오후 두 시 반") == ("14:30", 1.0), "공일공 → 010, 이십일 → 21, 오후 두 시 반 → 14:30이에요.")
check(date_itn("다음 주 수요일")[0] == date(2026, 11, 18) and date_itn("내일", date(2026, 11, 30))[0] == date(2026, 12, 1), "날짜는 오늘이 기준이에요.")

# 2) 확인 전략: 번호 · 이름은 늘 명시적, 확신이 낮으면 명시적
check(confirm_style("phone", 1.0) == "explicit" and confirm_style("name", 1.0) == "explicit" and confirm_style("time", 0.6) == "explicit" and confirm_style("date", 0.9) == "implicit", "정책이 표와 같아야 해요.")
check(say_value("phone", "010-1234-5678") == "공일공, 일이삼사, 오육칠팔", "번호는 묶음마다 한 글자씩 읽어요.")

# 3) 상태 머신: 시나리오 9개
bad = [name for name, turns, want in SCENARIOS if not verdict(run(turns)[0], want)]
print("실패한 시나리오:", bad or "없음")
check(not bad, "시나리오 9개가 모두 통과해야 해요.")

# 4) 복구: 못 알아들음 3번 → 상담원 · 침묵 2번 → 종료 · 규칙 위반 → 해당 슬롯만 다시
check(MAX_MISS == 3 and MAX_SILENCE == 2 and run(["어...", "음", "아"])[0].state == "handoff" and run([SILENCE, SILENCE])[0].state == "end", "실패 3번이면 상담원, 침묵 2번이면 종료예요.")
dm, log = run(["다음 주 월요일 오전 열한 시 충치 치료", "강도윤입니다", "네", "공일공 일일일일 이이이이", "네", "아니요 일요일로 해 주세요"])
check(dm.state == "collect" and dm.need() == "date" and "일요일은 쉬어요" in log[-1][1], f"일요일은 거절하고 날짜만 다시 물어요: {log[-1][1]}")

# 5) 하이브리드: 예약 밖 질문만 LLM
