];

function verdict(dm: DialogManager, want: Record<string, string>): boolean {
  const got: Record<string, string> = { state: dm.state, ...dm.slots };
  return Object.entries(want).every(([k, v]) => got[k] === v);
}

// 1) ITN: 말한 그대로가 아니라 시스템이 쓰는 값으로
check(spokenDigits("공일공") === "010" && sinoToInt("이십일") === 21 && JSON.stringify(timeItn("오후 두 시 반")) === '["14:30",1]', "공일공 → 010, 이십일 → 21, 오후 두 시 반 → 14:30이에요.");
check(dateItn("다음 주 수요일")?.[0] === "2026-11-18" && dateItn("내일", "2026-11-30")?.[0] === "2026-12-01", "날짜는 오늘이 기준이에요.");

// 2) 확인 전략: 번호 · 이름은 늘 명시적, 확신이 낮으면 명시적
check(confirmStyle("phone", 1.0) === "explicit" && confirmStyle("name", 1.0) === "explicit" && confirmStyle("time", 0.6) === "explicit" && confirmStyle("date", 0.9) === "implicit", "정책이 표와 같아야 해요.");
check(sayValue("phone", "010-1234-5678") === "공일공, 일이삼사, 오육칠팔", "번호는 묶음마다 한 글자씩 읽어요.");

// 3) 상태 머신: 시나리오 9개
const bad = SCENARIOS.filter(([, turns, want]) => !verdict(run(turns)[0], want)).map((s) => s[0]);
console.log("실패한 시나리오:", bad.length ? bad : "없음");
check(bad.length === 0, "시나리오 9개가 모두 통과해야 해요.");

// 4) 복구: 못 알아들음 3번 → 상담원 · 침묵 2번 → 종료 · 규칙 위반 → 해당 슬롯만 다시
check(MAX_MISS === 3 && MAX_SILENCE === 2 && run(["어...", "음", "아"])[0].state === "handoff" && run([SILENCE, SILENCE])[0].state === "end", "실패 3번이면 상담원, 침묵 2번이면 종료예요.");
const [dm, log] = run(["다음 주 월요일 오전 열한 시 충치 치료", "강도윤입니다", "네", "공일공 일일일일 이이이이", "네", "아니요 일요일로 해 주세요"]);
check(dm.state === "collect" && dm.need() === "date" && log[log.length - 1][1].includes("일요일은 쉬어요"), `일요일은 거절하고 날짜만 다시 물어요: ${log[log.length - 1][1]}`);

// 5) 하이브리드: 예약 밖 질문만 LLM
const dm2 = new DialogManager();
const r = dm2.step("주차는 되나요?");
check(r.kind === "free" && r.text.includes("주차") && dm2.need() === "service", "LLM이 답하되 하던 질문(진료)으로 돌아와요.");
